const inp = $('Execute Workflow Trigger').first().json;
const wa_id = String(inp.wa_id || '').trim();
if (!wa_id) throw new Error('MISSING_WA_ID: wa_id is required.');
let data;
try { data = typeof inp.lead_data === 'string' ? JSON.parse(inp.lead_data) : (inp.lead_data || {}); }
catch (e) { throw new Error('INVALID_LEAD_DATA: lead_data must be a valid JSON object string, e.g. {"budget":"80 lakh"}'); }
const BLOCKED = ['id', 'created_at', 'updated_at', 'wa_id'];
const EMPTY = ['', 'null', 'undefined', 'unknown', 'n/a', 'na', 'none'];
const body = { wa_id };
for (const [k, v] of Object.entries(data)) {
  if (BLOCKED.includes(k)) continue;
  if (v === null || v === undefined) continue;
  if (typeof v === 'string' && EMPTY.includes(v.trim().toLowerCase())) continue;
  body[k] = v;
}
if (body.lead_score !== undefined) body.lead_score = Number(body.lead_score);
if (Object.keys(body).length === 1) throw new Error('NOTHING_TO_SAVE: lead_data had no non-empty fields.');
return [{ json: { body, saved_fields: Object.keys(body).filter(k => k !== 'wa_id') } }];

const rows = $input.all().map(i => i.json);
const row = Array.isArray(rows[0]) ? rows[0][0] : rows[0];
const fields = $('Clean Fields').first().json.saved_fields;
if (!row || !row.id) throw new Error('SAVE_FAILED: Supabase returned no row.');
return [{ json: { success: true, lead_id: row.id, saved_fields: fields,
  lead_score: row.lead_score ?? null, lead_temperature: row.lead_temperature ?? null,
  message: 'Lead saved successfully. Use lead_id for approval requests.' } }];

const inp = $('Execute Workflow Trigger').first().json;
const wa_id = String(inp.wa_id || '').trim();
if (!wa_id) throw new Error('MISSING_WA_ID: wa_id is required.');
let data;
try { data = typeof inp.lead_data === 'string' ? JSON.parse(inp.lead_data) : (inp.lead_data || {}); }
catch (e) { throw new Error('INVALID_LEAD_DATA: lead_data must be a valid JSON object string, e.g. {"budget":"80 lakh"}'); }
// columns that exist in buyer_leads (wa_id and phone_number are handled automatically)
const ALLOWED = ['lead_name','email','property_type','location','bedrooms','property_size','budget','purchase_timeline','financing_status',
  'purchase_purpose','requirements','priority_match','matched_properties','conversation_summary','lead_score','lead_temperature',
  'appointment_requested','appointment_confirmed','appointment_time','appointment_event_id'];
const ALIAS = { property_location: 'location', name: 'lead_name', customer_name: 'lead_name', summary: 'conversation_summary' };
const EMPTY = ['', 'null', 'undefined', 'unknown', 'n/a', 'na', 'none'];
const body = { wa_id }, ignored = [];
for (let [k, v] of Object.entries(data)) {
  k = ALIAS[k] || k;
  if (v === null || v === undefined) continue;
  if (typeof v === 'string' && EMPTY.includes(v.trim().toLowerCase())) continue;
  if (!ALLOWED.includes(k)) { ignored.push(k); continue; }
  body[k] = v;
}
if (body.lead_score !== undefined) {
  const m = String(body.lead_score).match(/-?\d+(\.\d+)?/); const n = m ? Math.round(parseFloat(m[0])) : NaN;
  if (isNaN(n)) delete body.lead_score; else body.lead_score = Math.max(0, Math.min(100, n));
}
if (body.lead_temperature !== undefined) body.lead_temperature = String(body.lead_temperature).trim().toUpperCase();
for (const b of ['appointment_requested', 'appointment_confirmed'])
  if (body[b] !== undefined) body[b] = body[b] === true || String(body[b]).toLowerCase() === 'true';
if (Object.keys(body).length === 1) throw new Error('NOTHING_TO_SAVE: no valid non-empty fields. Allowed fields: ' + ALLOWED.join(', '));
return [{ json: { body, saved_fields: Object.keys(body).filter(k => k !== 'wa_id'), ignored_fields: ignored } }];

const rows = $input.all().map(i => i.json);
const row = Array.isArray(rows[0]) ? rows[0][0] : rows[0];
const fields = $('Clean Fields1').first().json.saved_fields;
if (!row || !row.id) throw new Error('SAVE_FAILED: Supabase returned no row.');
return [{ json: { success: true, lead_id: row.id, saved_fields: fields, ignored_fields: $('Clean Fields1').first().json.ignored_fields,
  lead_score: row.lead_score ?? null, lead_temperature: row.lead_temperature ?? null,
  message: 'Lead saved successfully. Use lead_id for approval requests.' } }];
